{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Fatal Error",
          "intent": "Establish the protagonist's mundane death and the jarring transition into the System tutorial.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Protagonist awakens in the white-room tutorial space and receives the first System prompt."
        },
        {
          "section_id": 2,
          "title": "Identifying the Glitch",
          "intent": "Introduce the combat mechanics and the first realization that the Crit multiplier is behaving abnormally.",
          "section_role": "trial",
          "target_scene_count": 3,
          "end_condition": "Protagonist successfully triggers a 100x crit on a training dummy, causing a physics error."
        },
        {
          "section_id": 3,
          "title": "The First Payday",
          "intent": "Show the protagonist intentionally using the glitch to secure high-value loot from the first tutorial mob.",
          "section_role": "payoff",
          "target_scene_count": 3,
          "end_condition": "Protagonist loots a 'Legendary' starter dagger from a common tutorial rat due to overkill bonuses."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "The Overkill Protocol",
          "intent": "The protagonist tests the limits of the 'Crit' multiplier to maximize loot drops across multiple encounters.",
          "section_role": "investigation",
          "target_scene_count": 3,
          "end_condition": "Protagonist confirms that damage exceeding 1000% of enemy HP guarantees a rarity tier jump."
        },
        {
          "section_id": 2,
          "title": "Boss Room Bypass",
          "intent": "A high-intensity fight where the protagonist uses the glitch to one-shot the Tutorial Boss.",
          "section_role": "trial",
          "target_scene_count": 4,
          "end_condition": "The Tutorial Boss is vaporized by a single strike, dropping a unique 'Glitched' item."
        },
        {
          "section_id": 3,
          "title": "Graduation Day",
          "intent": "The protagonist prepares to leave the tutorial zone with an inventory full of unintended gear.",
          "section_role": "transition",
          "target_scene_count": 3,
          "end_condition": "Protagonist steps through the tutorial exit portal into the main game world."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "High Stakes in the Hub",
          "intent": "Introduce the local merchant lord and the 'Impossible' quest offer.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Protagonist signs the soul-bound contract for the quest 'The Heart of the Glitch'."
        },
        {
          "section_id": 2,
          "title": "The Glass Cannon's Journey",
          "intent": "The protagonist travels to the quest zone, using 'Hit and Run' tactics to avoid standard level-gated mobs.",
          "section_role": "trial",
          "target_scene_count": 3,
          "end_condition": "Protagonist arrives at the entrance of the Forbidden Archive."
        },
        {
          "section_id": 3,
          "title": "Exploiting the Terrain",
          "intent": "A combat-heavy sequence where the protagonist uses environment glitches to survive high-level enemies.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The quest objective is secured after the protagonist crits a support pillar to collapse the room on the boss."
        },
        {
          "section_id": 4,
          "title": "Unwanted Fame",
          "intent": "The protagonist escapes the zone just as the merchant's rivals arrive to investigate the damage.",
          "section_role": "payoff",
          "target_scene_count": 2,
          "end_condition": "Protagonist hides in the city slums, realizing he is now a person of interest."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Unseen Eye",
          "intent": "Establish the presence of System Sentinels and the feeling of being hunted by the game itself.",
          "section_role": "investigation",
          "target_scene_count": 3,
          "end_condition": "Protagonist narrowly avoids a deletion beam from a cloaked Sentinel."
        },
        {
          "section_id": 2,
          "title": "Breadcrumbs of the Devs",
          "intent": "The protagonist follows clues regarding the origin of the 'Crit' glitch.",
          "section_role": "investigation",
          "target_scene_count": 3,
          "end_condition": "Protagonist decrypts a message leading to the 'Null Sector' where the Admin is hiding."
        },
        {
          "section_id": 3,
          "title": "The Admin's Door",
          "intent": "The protagonist navigates a non-Euclidean dungeon to reach the Admin's sanctuary.",
          "section_role": "transition",
          "target_scene_count": 3,
          "end_condition": "Protagonist meets the disgraced Admin and learns the truth about the 'Developer Tool'."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "The Bounty is Set",
          "intent": "The protagonist prepares the safe-haven for an inevitable assault by bounty hunters.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The first wave of bounty hunters arrives at the sanctuary gates."
        },
        {
          "section_id": 2,
          "title": "The Guerilla Defense",
          "intent": "Showcase the 'Hit and Run' strategy as the protagonist picks off hunters one by one.",
          "section_role": "trial",
          "target_scene_count": 4,
          "end_condition": "The bounty hunter leader is defeated with a 5000% overkill crit."
        },
        {
          "section_id": 3,
          "title": "The Patch Arrival",
          "intent": "The System sends multiple Sentinels to 'cleanse' the area, forcing the protagonist to flee.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The sanctuary is destroyed as the protagonist and the Admin escape into the sewers."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "Infiltrating the Core",
          "intent": "The protagonist sneaks into the Regional Core facility under the cover of a resistance distraction.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Protagonist bypasses the final security firewall of the Core."
        },
        {
          "section_id": 2,
          "title": "The Ascent of Errors",
          "intent": "Navigating the interior of the Core where reality is already beginning to warp.",
          "section_role": "trial",
          "target_scene_count": 3,
          "end_condition": "Protagonist reaches the central platform where the Level 99 Guardian awaits."
        },
        {
          "section_id": 3,
          "title": "Dividing by Zero",
          "intent": "The final battle where the protagonist pushes the 'Crit' glitch to its absolute breaking point.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The Guardian is deleted from the server logs by an infinite damage loop."
        },
        {
          "section_id": 4,
          "title": "Structural Failure",
          "intent": "The protagonist physically destroys the Core, initiating a regional shutdown.",
          "section_role": "aftermath",
          "target_scene_count": 2,
          "end_condition": "The Regional Core explodes, sending a shockwave through the game world."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The Falling Sky",
          "intent": "The protagonist must navigate the rapidly collapsing environment of the region.",
          "section_role": "pressure",
          "target_scene_count": 3,
          "end_condition": "Protagonist reaches the edge of the 'Dead Zone' created by the Core's destruction."
        },
        {
          "section_id": 2,
          "title": "The Border Run",
          "intent": "A desperate dash toward the Unmapped Zones while avoiding the last of the System's automated defenses.",
          "section_role": "trial",
          "target_scene_count": 3,
          "end_condition": "Protagonist crosses the invisible boundary into the Unmapped Zones."
        },
        {
          "section_id": 3,
          "title": "Beyond the Map",
          "intent": "Establish the new status quo and the protagonist's intent to keep exploiting the world.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "Protagonist looks out over a chaotic, lawless landscape and begins planning Book 2."
        }
      ]
    }
  ]
}

